import { createRoute, z } from '@hono/zod-openapi'

const AccountAnnualRevenueSchema = z
  .object({
    amount: z
      .int()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'A non-negative integer representing the amount in the [smallest currency unit](/currencies#zero-decimal).',
      }),
    currency: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Three-letter [ISO currency code](https://www.iso.org/iso-4217-currency-codes.html), in lowercase. Must be a [supported currency](https://stripe.com/docs/currencies).',
      }),
    fiscal_year_end: z
      .string()
      .max(5000)
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'The close-out date of the preceding fiscal year in ISO 8601 format. E.g. 2023-12-31 for the 31st of December, 2023.',
      }),
  })
  .openapi({
    description: '',
    title: 'AccountAnnualRevenue',
    'x-expandableFields': [],
    required: [],
  })
  .openapi('AccountAnnualRevenue')

const AccountMonthlyEstimatedRevenueSchema = z
  .object({
    amount: z
      .int()
      .openapi({
        description:
          'A non-negative integer representing how much to charge in the [smallest currency unit](/currencies#zero-decimal).',
      }),
    currency: z
      .string()
      .openapi({
        description:
          'Three-letter [ISO currency code](https://www.iso.org/iso-4217-currency-codes.html), in lowercase. Must be a [supported currency](https://stripe.com/docs/currencies).',
      }),
  })
  .openapi({
    description: '',
    required: ['amount', 'currency'],
    title: 'AccountMonthlyEstimatedRevenue',
    'x-expandableFields': [],
  })
  .openapi('AccountMonthlyEstimatedRevenue')

type AddressType = {
  city?: string | null
  country?: string | null
  line1?: string | null
  line2?: string | null
  postal_code?: string | null
  state?: string | null
}

const AddressSchema: z.ZodType<AddressType> = z
  .object({
    city: z
      .string()
      .max(5000)
      .nullable()
      .exactOptional()
      .openapi({ description: 'City, district, suburb, town, or village.' }),
    country: z
      .string()
      .max(5000)
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Two-letter country code ([ISO 3166-1 alpha-2](https://en.wikipedia.org/wiki/ISO_3166-1_alpha-2)).',
      }),
    line1: z
      .string()
      .max(5000)
      .nullable()
      .exactOptional()
      .openapi({ description: 'Address line 1, such as the street, PO Box, or company name.' }),
    line2: z
      .string()
      .max(5000)
      .nullable()
      .exactOptional()
      .openapi({ description: 'Address line 2, such as the apartment, suite, unit, or building.' }),
    postal_code: z
      .string()
      .max(5000)
      .nullable()
      .exactOptional()
      .openapi({ description: 'ZIP or postal code.' }),
    state: z
      .string()
      .max(5000)
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'State, county, province, or region ([ISO 3166-2](https://en.wikipedia.org/wiki/ISO_3166-2)).',
      }),
  })
  .openapi({ description: '', title: 'Address', 'x-expandableFields': [], required: [] })
  .openapi('Address')

type AccountBusinessProfileType = {
  annual_revenue?: z.infer<typeof AccountAnnualRevenueSchema> | null
  estimated_worker_count?: number | null
  mcc?: string | null
  minority_owned_business_designation?:
    | (
        | 'lgbtqi_owned_business'
        | 'minority_owned_business'
        | 'none_of_these_apply'
        | 'prefer_not_to_answer'
        | 'women_owned_business'
      )[]
    | null
  monthly_estimated_revenue?: z.infer<typeof AccountMonthlyEstimatedRevenueSchema>
  name?: string | null
  product_description?: string | null
  specified_commercial_transactions_act_url?: string | null
  support_address?: z.infer<typeof AddressSchema> | null
  support_email?: string | null
  support_phone?: string | null
  support_url?: string | null
  url?: string | null
}

const AccountBusinessProfileSchema: z.ZodType<AccountBusinessProfileType> = z
  .object({
    annual_revenue: z
      .union([AccountAnnualRevenueSchema])
      .nullable()
      .exactOptional()
      .openapi({
        description: "The applicant's gross annual revenue for its preceding fiscal year.",
      }),
    estimated_worker_count: z
      .int()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'An estimated upper bound of employees, contractors, vendors, etc. currently working for the business.',
      }),
    mcc: z
      .string()
      .max(5000)
      .nullable()
      .exactOptional()
      .openapi({
        description:
          '[The merchant category code for the account](/connect/setting-mcc). MCCs are used to classify businesses based on the goods or services they provide.',
      }),
    minority_owned_business_designation: z
      .array(
        z.enum([
          'lgbtqi_owned_business',
          'minority_owned_business',
          'none_of_these_apply',
          'prefer_not_to_answer',
          'women_owned_business',
        ]),
      )
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Whether the business is a minority-owned, women-owned, and/or LGBTQI+ -owned business.',
      }),
    monthly_estimated_revenue: AccountMonthlyEstimatedRevenueSchema.exactOptional(),
    name: z
      .string()
      .max(5000)
      .nullable()
      .exactOptional()
      .openapi({ description: 'The customer-facing business name.' }),
    product_description: z
      .string()
      .max(40000)
      .nullable()
      .exactOptional()
      .openapi({
        description:
          "Internal-only description of the product sold or service provided by the business. It's used by Stripe for risk and underwriting purposes.",
      }),
    specified_commercial_transactions_act_url: z
      .string()
      .max(5000)
      .nullable()
      .exactOptional()
      .openapi({
        description:
          "A link to the business's publicly available terms related to the Specified Commercial Transaction Act. Only used for accounts in Japan.",
      }),
    support_address: z
      .union([AddressSchema])
      .nullable()
      .exactOptional()
      .openapi({
        description: 'A publicly available mailing address for sending support issues to.',
      }),
    support_email: z
      .string()
      .max(5000)
      .nullable()
      .exactOptional()
      .openapi({
        description: 'A publicly available email address for sending support issues to.',
      }),
    support_phone: z
      .string()
      .max(5000)
      .nullable()
      .exactOptional()
      .openapi({ description: 'A publicly available phone number to call with support issues.' }),
    support_url: z
      .string()
      .max(5000)
      .nullable()
      .exactOptional()
      .openapi({ description: 'A publicly available website for handling support issues.' }),
    url: z
      .string()
      .max(5000)
      .nullable()
      .exactOptional()
      .openapi({ description: "The business's publicly available website." }),
  })
  .openapi({
    description: '',
    title: 'AccountBusinessProfile',
    'x-expandableFields': ['annual_revenue', 'monthly_estimated_revenue', 'support_address'],
    required: [],
  })
  .openapi('AccountBusinessProfile')

