type IssuingTokenType = {
  card: string | z.infer<typeof IssuingCardSchema>
  created: number
  device_fingerprint?: string | null
  id: string
  last4?: string
  livemode: boolean
  network: 'mastercard' | 'visa'
  network_data?: z.infer<typeof IssuingNetworkTokenNetworkDataSchema>
  network_updated_at: number
  object: 'issuing.token'
  status: 'active' | 'deleted' | 'requested' | 'suspended'
  wallet_provider?: 'apple_pay' | 'google_pay' | 'samsung_pay'
}

const IssuingTokenSchema: z.ZodType<IssuingTokenType> = z
  .object({
    card: z
      .union([z.string().max(5000), IssuingCardSchema])
      .openapi({
        description: 'Card associated with this token.',
        'x-expansionResources': { oneOf: [{ $ref: '#/components/schemas/issuing.card' }] },
      }),
    created: z
      .int()
      .openapi({
        description:
          'Time at which the object was created. Measured in seconds since the Unix epoch.',
      }),
    device_fingerprint: z
      .string()
      .max(5000)
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'The hashed ID derived from the device ID from the card network associated with the token.',
      }),
    id: z.string().max(5000).openapi({ description: 'Unique identifier for the object.' }),
    last4: z
      .string()
      .max(5000)
      .exactOptional()
      .openapi({ description: 'The last four digits of the token.' }),
    livemode: z
      .boolean()
      .openapi({
        description:
          'If the object exists in live mode, the value is `true`. If the object exists in test mode, the value is `false`.',
      }),
    network: z
      .enum(['mastercard', 'visa'])
      .openapi({
        description: 'The token service provider / card network associated with the token.',
      }),
    network_data: IssuingNetworkTokenNetworkDataSchema.exactOptional(),
    network_updated_at: z
      .int()
      .openapi({
        description:
          'Time at which the token was last updated by the card network. Measured in seconds since the Unix epoch.',
      }),
    object: z
      .literal('issuing.token')
      .openapi({
        description:
          "String representing the object's type. Objects of the same type share the same value.",
      }),
    status: z
      .enum(['active', 'deleted', 'requested', 'suspended'])
      .openapi({ description: 'The usage state of the token.' }),
    wallet_provider: z
      .enum(['apple_pay', 'google_pay', 'samsung_pay'])
      .exactOptional()
      .openapi({ description: 'The digital wallet for this token, if one was used.' }),
  })
  .openapi({
    description:
      'An issuing token object is created when an issued card is added to a digital wallet. As a [card issuer](https://docs.stripe.com/issuing), you can [view and manage these tokens](https://docs.stripe.com/issuing/controls/token-management) through Stripe.',
    required: [
      'card',
      'created',
      'id',
      'livemode',
      'network',
      'network_updated_at',
      'object',
      'status',
    ],
    title: 'Token',
    'x-expandableFields': ['card', 'network_data'],
    'x-resourceId': 'issuing.token',
  })
  .openapi('IssuingToken')

