  cardholder?: (string | z.infer<typeof IssuingCardholderSchema>) | null
  created: number
  currency: string
  fleet?: z.infer<typeof IssuingAuthorizationFleetDataSchema> | null
  fraud_challenges?: z.infer<typeof IssuingAuthorizationFraudChallengeSchema>[] | null
  fuel?: z.infer<typeof IssuingAuthorizationFuelDataSchema> | null
  id: string
  livemode: boolean
  merchant_amount: number
  merchant_currency: string
  merchant_data: z.infer<typeof IssuingAuthorizationMerchantDataSchema>
  metadata: { [key: string]: string }
