  object: 'issuing.authorization'
  pending_request?: z.infer<typeof IssuingAuthorizationPendingRequestSchema> | null
  request_history: z.infer<typeof IssuingAuthorizationRequestSchema>[]
  status: 'closed' | 'expired' | 'pending' | 'reversed'
  token?: (string | z.infer<typeof IssuingTokenSchema>) | null
  transactions: z.infer<typeof IssuingTransactionSchema>[]
  treasury?: z.infer<typeof IssuingAuthorizationTreasurySchema> | null
