const IssuingPhysicalBundleFeaturesSchema = z
  .object({
    card_logo: z
      .enum(['optional', 'required', 'unsupported'])
      .openapi({
        description:
          'The policy for how to use card logo images in a card design with this physical bundle.',
      }),
    carrier_text: z
      .enum(['optional', 'required', 'unsupported'])
      .openapi({
        description:
          'The policy for how to use carrier letter text in a card design with this physical bundle.',
      }),
    second_line: z
      .enum(['optional', 'required', 'unsupported'])
      .openapi({
        description: 'The policy for how to use a second line on a card with this physical bundle.',
      }),
  })
  .openapi({
    description: '',
    required: ['card_logo', 'carrier_text', 'second_line'],
    title: 'IssuingPhysicalBundleFeatures',
    'x-expandableFields': [],
  })
  .openapi('IssuingPhysicalBundleFeatures')

const IssuingPhysicalBundleSchema = z
  .object({
    features: IssuingPhysicalBundleFeaturesSchema,
    id: z.string().max(5000).openapi({ description: 'Unique identifier for the object.' }),
    livemode: z
      .boolean()
      .openapi({
        description:
          'If the object exists in live mode, the value is `true`. If the object exists in test mode, the value is `false`.',
      }),
    name: z.string().max(5000).openapi({ description: 'Friendly display name.' }),
    object: z
      .literal('issuing.physical_bundle')
      .openapi({
        description:
          "String representing the object's type. Objects of the same type share the same value.",
      }),
    status: z
      .enum(['active', 'inactive', 'review'])
      .openapi({ description: 'Whether this physical bundle can be used to create cards.' }),
    type: z
      .enum(['custom', 'standard'])
      .openapi({
        description:
          'Whether this physical bundle is a standard Stripe offering or custom-made for you.',
      }),
  })
  .openapi({
    description:
      'A Physical Bundle represents the bundle of physical items - card stock, carrier letter, and envelope - that is shipped to a cardholder when you create a physical card.',
    required: ['features', 'id', 'livemode', 'name', 'object', 'status', 'type'],
    title: 'Physical Bundle',
    'x-expandableFields': ['features'],
    'x-resourceId': 'issuing.physical_bundle',
  })
  .openapi('IssuingPhysicalBundle')

const IssuingPersonalizationDesignPreferencesSchema = z
  .object({
    is_default: z
      .boolean()
      .openapi({
        description:
          "Whether we use this personalization design to create cards when one isn't specified. A connected account uses the Connect platform's default design if no personalization design is set as the default design.",
      }),
    is_platform_default: z
      .boolean()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Whether this personalization design is used to create cards when one is not specified and a default for this connected account does not exist.',
      }),
  })
  .openapi({
    description: '',
    required: ['is_default'],
    title: 'IssuingPersonalizationDesignPreferences',
    'x-expandableFields': [],
  })
  .openapi('IssuingPersonalizationDesignPreferences')

const IssuingPersonalizationDesignRejectionReasonsSchema = z
  .object({
    card_logo: z
      .array(
        z.enum([
          'geographic_location',
          'inappropriate',
          'network_name',
          'non_binary_image',
          'non_fiat_currency',
          'other',
          'other_entity',
          'promotional_material',
        ]),
      )
      .nullable()
      .exactOptional()
      .openapi({ description: 'The reason(s) the card logo was rejected.' }),
    carrier_text: z
      .array(
        z.enum([
          'geographic_location',
          'inappropriate',
          'network_name',
          'non_fiat_currency',
          'other',
          'other_entity',
          'promotional_material',
        ]),
      )
      .nullable()
      .exactOptional()
      .openapi({ description: 'The reason(s) the carrier text was rejected.' }),
  })
  .openapi({
    description: '',
    title: 'IssuingPersonalizationDesignRejectionReasons',
    'x-expandableFields': [],
    required: [],
  })
  .openapi('IssuingPersonalizationDesignRejectionReasons')

const IssuingPersonalizationDesignSchema = z
  .object({
    card_logo: z
      .union([z.string().max(5000), FileSchema])
      .nullable()
      .exactOptional()
      .openapi({
        description:
          "The file for the card logo to use with physical bundles that support card logos. Must have a `purpose` value of `issuing_logo`. Image must be in PNG format with dimensions of 1000px by 200px. It must be a binary (black and white) image containing a black logo on a white background. We don't accept grayscale.",
        'x-expansionResources': { oneOf: [{ $ref: '#/components/schemas/file' }] },
      }),
    carrier_text: z
      .union([IssuingPersonalizationDesignCarrierTextSchema])
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Hash containing carrier text, for use with physical bundles that support carrier text.',
      }),
    created: z
      .int()
      .openapi({
        description:
          'Time at which the object was created. Measured in seconds since the Unix epoch.',
      }),
    id: z.string().max(5000).openapi({ description: 'Unique identifier for the object.' }),
    livemode: z
      .boolean()
      .openapi({
        description:
          'If the object exists in live mode, the value is `true`. If the object exists in test mode, the value is `false`.',
      }),
    lookup_key: z
      .string()
      .max(5000)
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'A lookup key used to retrieve personalization designs dynamically from a static string. This may be up to 200 characters.',
      }),
    metadata: z
      .record(z.string(), z.string().max(500))
      .openapi({
        description:
          'Set of [key-value pairs](https://docs.stripe.com/api/metadata) that you can attach to an object. This can be useful for storing additional information about the object in a structured format.',
      }),
    name: z
      .string()
      .max(5000)
      .nullable()
      .exactOptional()
      .openapi({ description: 'Friendly display name.' }),
    object: z
      .literal('issuing.personalization_design')
      .openapi({
        description:
          "String representing the object's type. Objects of the same type share the same value.",
      }),
    physical_bundle: z
      .union([z.string().max(5000), IssuingPhysicalBundleSchema])
      .openapi({
        description: 'The physical bundle object belonging to this personalization design.',
        'x-expansionResources': {
          oneOf: [{ $ref: '#/components/schemas/issuing.physical_bundle' }],
        },
      }),
    preferences: IssuingPersonalizationDesignPreferencesSchema,
    rejection_reasons: IssuingPersonalizationDesignRejectionReasonsSchema,
    status: z
      .enum(['active', 'inactive', 'rejected', 'review'])
      .openapi({ description: 'Whether this personalization design can be used to create cards.' }),
  })
  .openapi({
    description:
      'A Personalization Design is a logical grouping of a Physical Bundle, card logo, and carrier text that represents a product line.',
    required: [
      'created',
      'id',
      'livemode',
      'metadata',
      'object',
      'physical_bundle',
      'preferences',
      'rejection_reasons',
      'status',
    ],
    title: 'Personalization Design',
    'x-expandableFields': [
      'card_logo',
      'carrier_text',
      'physical_bundle',
      'preferences',
      'rejection_reasons',
    ],
    'x-resourceId': 'issuing.personalization_design',
  })
  .openapi('IssuingPersonalizationDesign')

const IssuingCardShippingAddressValidationSchema = z
  .object({
    mode: z
      .enum(['disabled', 'normalization_only', 'validation_and_normalization'])
      .openapi({ description: 'The address validation capabilities to use.' }),
    normalized_address: z
      .union([AddressSchema])
      .nullable()
      .exactOptional()
      .openapi({ description: 'The normalized shipping address.' }),
    result: z
      .enum(['indeterminate', 'likely_deliverable', 'likely_undeliverable'])
      .nullable()
      .exactOptional()
      .openapi({ description: 'The validation result for the shipping address.' }),
  })
  .openapi({
    description: '',
    required: ['mode'],
    title: 'IssuingCardShippingAddressValidation',
    'x-expandableFields': ['normalized_address'],
  })
  .openapi('IssuingCardShippingAddressValidation')

const IssuingCardShippingCustomsSchema = z
  .object({
    eori_number: z
      .string()
      .max(5000)
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'A registration number used for customs in Europe. See [https://www.gov.uk/eori](https://www.gov.uk/eori) for the UK and [https://ec.europa.eu/taxation_customs/business/customs-procedures-import-and-export/customs-procedures/economic-operators-registration-and-identification-number-eori_en](https://ec.europa.eu/taxation_customs/business/customs-procedures-import-and-export/customs-procedures/economic-operators-registration-and-identification-number-eori_en) for the EU.',
      }),
  })
  .openapi({
    description: '',
    title: 'IssuingCardShippingCustoms',
    'x-expandableFields': [],
    required: [],
  })
  .openapi('IssuingCardShippingCustoms')

const IssuingCardShippingSchema = z
  .object({
    address: AddressSchema,
    address_validation: z
      .union([IssuingCardShippingAddressValidationSchema])
      .nullable()
      .exactOptional()
      .openapi({ description: 'Address validation details for the shipment.' }),
    business_name: z
      .string()
      .max(5000)
      .nullable()
      .exactOptional()
      .openapi({
        description:
          "The name of the business at the shipping address, used on the shipping label to ensure delivery when the card is shipped to a cardholder's workplace.",
      }),
    carrier: z
      .enum(['correos', 'dhl', 'fedex', 'royal_mail', 'usps'])
      .nullable()
      .exactOptional()
      .openapi({ description: 'The delivery company that shipped a card.' }),
    customs: z
      .union([IssuingCardShippingCustomsSchema])
      .nullable()
      .exactOptional()
      .openapi({
        description: 'Additional information that may be required for clearing customs.',
      }),
    eta: z
      .int()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'A unix timestamp representing a best estimate of when the card will be delivered.',
      }),
    name: z.string().max(5000).openapi({ description: 'Recipient name.' }),
    phone_number: z
      .string()
      .max(5000)
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'The phone number of the receiver of the shipment. Our courier partners will use this number to contact you in the event of card delivery issues. For individual shipments to the EU/UK, if this field is empty, we will provide them with the phone number provided when the cardholder was initially created.',
      }),
    require_signature: z
      .boolean()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Whether a signature is required for card delivery. This feature is only supported for US users. Standard shipping service does not support signature on delivery. The default value for standard shipping service is false and for express and priority services is true.',
      }),
    service: z
      .enum(['express', 'priority', 'standard'])
      .openapi({
        description: 'Shipment service, such as `standard` or `express`.',
        'x-stripeBypassValidation': true,
      }),
    status: z
      .enum(['canceled', 'delivered', 'failure', 'pending', 'returned', 'shipped', 'submitted'])
      .nullable()
      .exactOptional()
      .openapi({ description: 'The delivery status of the card.' }),
    tracking_number: z
      .string()
      .max(5000)
      .nullable()
      .exactOptional()
      .openapi({ description: 'A tracking number for a card shipment.' }),
    tracking_url: z
      .string()
      .max(5000)
      .nullable()
      .exactOptional()
      .openapi({
        description:
          "A link to the shipping carrier's site where you can view detailed information about a card shipment.",
      }),
    type: z.enum(['bulk', 'individual']).openapi({ description: 'Packaging options.' }),
  })
  .openapi({
    description: '',
    required: ['address', 'name', 'service', 'type'],
    title: 'IssuingCardShipping',
    'x-expandableFields': ['address', 'address_validation', 'customs'],
  })
  .openapi('IssuingCardShipping')

