export const postV1AccountLinksRoute = createRoute({
  method: 'post',
  path: '/v1/account_links',
  summary: 'Create an account link',
  description:
    '<p>Creates an AccountLink object that includes a single-use Stripe URL that the platform can redirect their user to in order to take them through the Connect Onboarding flow.</p>',
  operationId: 'PostAccountLinks',
  request: {
    body: {
      content: {
        'application/x-www-form-urlencoded': {
          schema: z
            .strictObject({
              account: z
                .string()
                .max(5000)
                .openapi({
                  description: 'The identifier of the account to create an account link for.',
                }),
              collect: z
                .enum(['currently_due', 'eventually_due'])
                .exactOptional()
                .openapi({
                  description:
                    'The collect parameter is deprecated. Use `collection_options` instead.',
                }),
              collection_options: z
                .object({
                  fields: z.enum(['currently_due', 'eventually_due']).exactOptional(),
                  future_requirements: z.enum(['include', 'omit']).exactOptional(),
                })
                .exactOptional()
                .openapi({
                  description:
                    'Specifies the requirements that Stripe collects from connected accounts in the Connect Onboarding flow.',
                  title: 'collection_options_params',
                  required: [],
                }),
              expand: z
                .preprocess(
                  (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                  z.array(z.string().max(5000)),
                )
                .exactOptional()
                .openapi({
                  description: 'Specifies which fields in the response should be expanded.',
                }),
              refresh_url: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    "The URL the user will be redirected to if the account link is expired, has been previously-visited, or is otherwise invalid. The URL you specify should attempt to generate a new account link with the same parameters used to create the original account link, then redirect the user to the new account link's URL so they can continue with Connect Onboarding. If a new account link cannot be generated or the redirect fails you should display a useful error to the user.",
                }),
              return_url: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'The URL that the user will be redirected to upon leaving or completing the linked flow.',
                }),
              type: z
                .enum(['account_onboarding', 'account_update'])
                .openapi({
                  description:
                    "The type of account link the user is requesting.\n\nYou can create Account Links of type `account_update` only for connected accounts where your platform is responsible for collecting requirements, including Custom accounts. You can't create them for accounts that have access to a Stripe-hosted Dashboard. If you use [Connect embedded components](/connect/get-started-connect-embedded-components), you can include components that allow your connected accounts to update their own information. For an account without Stripe-hosted Dashboard access where Stripe is liable for negative balances, you must use embedded components.",
                  'x-stripeBypassValidation': true,
                }),
            })
            .openapi({ required: ['account', 'type'] }),
          encoding: { collection_options: {}, expand: {} },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Successful response.',
      content: { 'application/json': { schema: AccountLinkSchema } },
    },
    default: {
      description: 'Error response.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
})

