export const getV1AccountsRoute = createRoute({
  method: 'get',
  path: '/v1/accounts',
  summary: 'List all connected accounts',
  description:
    '<p>Returns a list of accounts connected to your platform via <a href="/docs/connect">Connect</a>. If you’re not a platform, the list is empty.</p>',
  operationId: 'GetAccounts',
  request: {
    query: z.object({
      created: z
        .union([
          z
            .object({
              gt: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .exactOptional(),
              gte: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .exactOptional(),
              lt: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .exactOptional(),
              lte: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .exactOptional(),
            })
            .openapi({ title: 'range_query_specs', required: [] }),
          z.preprocess(
            (val) =>
              typeof val === 'string' &&
              /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
              (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                ? Number(val)
                : val,
            z.int(),
          ),
        ])
        .exactOptional()
        .openapi({
          param: {
            description:
              'Only return connected accounts that were created during the given date interval.',
            explode: true,
            in: 'query',
            name: 'created',
            required: false,
            schema: {
              anyOf: [
                {
                  properties: {
                    gt: { type: 'integer' },
                    gte: { type: 'integer' },
                    lt: { type: 'integer' },
                    lte: { type: 'integer' },
                  },
                  title: 'range_query_specs',
                  type: 'object',
                },
                { type: 'integer' },
              ],
            },
            style: 'deepObject',
          },
        }),
      ending_before: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'A cursor for use in pagination. `ending_before` is an object ID that defines your place in the list. For instance, if you make a list request and receive 100 objects, starting with `obj_bar`, your subsequent call can include `ending_before=obj_bar` in order to fetch the previous page of the list.',
            in: 'query',
            name: 'ending_before',
            required: false,
            schema: { type: 'string' },
            style: 'form',
          },
        }),
      expand: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.string().max(5000)),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'Specifies which fields in the response should be expanded.',
            explode: true,
            in: 'query',
            name: 'expand',
            required: false,
            schema: { items: { maxLength: 5000, type: 'string' }, type: 'array' },
            style: 'deepObject',
          },
        }),
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'A limit on the number of objects to be returned. Limit can range between 1 and 100, and the default is 10.',
            in: 'query',
            name: 'limit',
            required: false,
            schema: { type: 'integer' },
            style: 'form',
          },
        }),
      starting_after: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'A cursor for use in pagination. `starting_after` is an object ID that defines your place in the list. For instance, if you make a list request and receive 100 objects, ending with `obj_foo`, your subsequent call can include `starting_after=obj_foo` in order to fetch the next page of the list.',
            in: 'query',
            name: 'starting_after',
            required: false,
            schema: { type: 'string' },
            style: 'form',
          },
        }),
    }),
    body: { content: { 'application/x-www-form-urlencoded': { schema: z.strictObject({}) } } },
  },
  responses: {
    200: {
      description: 'Successful response.',
      content: {
        'application/json': {
          schema: z
            .object({
              data: z.array(AccountSchema),
              has_more: z
                .boolean()
                .openapi({
                  description:
                    'True if this list has another page of items after this one that can be fetched.',
                }),
              object: z
                .literal('list')
                .openapi({
                  description:
                    "String representing the object's type. Objects of the same type share the same value. Always has the value `list`.",
                }),
              url: z
                .string()
                .regex(/^\/v1\/accounts/)
                .max(5000)
                .openapi({ description: 'The URL where this list can be accessed.' }),
            })
            .openapi({
              description: '',
              required: ['data', 'has_more', 'object', 'url'],
              title: 'AccountList',
              'x-expandableFields': ['data'],
            }),
        },
      },
    },
    default: {
      description: 'Error response.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
})

