export const getV1AccountsAccountRoute = createRoute({
  method: 'get',
  path: '/v1/accounts/{account}',
  summary: 'Retrieve account',
  description: '<p>Retrieves the details of an account.</p>',
  operationId: 'GetAccountsAccount',
  request: {
    params: z.object({
      account: z
        .string()
        .max(5000)
        .openapi({
          param: {
            in: 'path',
            name: 'account',
            required: true,
            schema: { maxLength: 5000, type: 'string' },
            style: 'simple',
          },
        }),
    }),
    query: z.object({
      expand: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.string().max(5000)),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'Specifies which fields in the response should be expanded.',
            explode: true,
            in: 'query',
            name: 'expand',
            required: false,
            schema: { items: { maxLength: 5000, type: 'string' }, type: 'array' },
            style: 'deepObject',
          },
        }),
    }),
    body: { content: { 'application/x-www-form-urlencoded': { schema: z.strictObject({}) } } },
  },
  responses: {
    200: {
      description: 'Successful response.',
      content: { 'application/json': { schema: AccountSchema } },
    },
    default: {
      description: 'Error response.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
})

