export const postV1ChargesChargeCaptureRoute = createRoute({
  method: 'post',
  path: '/v1/charges/{charge}/capture',
  summary: 'Capture a charge',
  description:
    '<p>This method is deprecated and will be removed soon. If your integration uses it, you need to update it to use a different payment flow, such as <a href="/docs/payments/payment-intents">the Payment Intents API</a>.</p>',
  operationId: 'PostChargesChargeCapture',
  request: {
    params: z.object({
      charge: z
        .string()
        .max(5000)
        .openapi({
          param: {
            in: 'path',
            name: 'charge',
            required: true,
            schema: { maxLength: 5000, type: 'string' },
            style: 'simple',
          },
        }),
    }),
    body: {
      content: {
        'application/x-www-form-urlencoded': {
          schema: z
            .strictObject({
              amount: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .exactOptional()
                .openapi({
                  description:
                    'The amount to capture, which must be less than or equal to the original amount.',
                }),
              application_fee: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .exactOptional()
                .openapi({ description: 'An application fee to add on to this charge.' }),
              application_fee_amount: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .exactOptional()
                .openapi({
                  description:
                    'An application fee amount to add on to this charge, which must be less than or equal to the original amount.',
                }),
              expand: z
                .preprocess(
                  (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                  z.array(z.string().max(5000)),
                )
                .exactOptional()
                .openapi({
                  description: 'Specifies which fields in the response should be expanded.',
                }),
              receipt_email: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    "The email address to send this charge's receipt to. This will override the previously-specified email address for this charge, if one was set. Receipts will not be sent in test mode.",
                }),
              statement_descriptor: z
                .string()
                .max(22)
                .exactOptional()
                .openapi({
                  description:
                    "For a non-card charge, text that appears on the customer's statement as the statement descriptor. This value overrides the account's default statement descriptor. For information about requirements, including the 22-character limit, see [the Statement Descriptor docs](https://docs.stripe.com/get-started/account/statement-descriptors).\n\nFor a card charge, this value is ignored unless you don't specify a `statement_descriptor_suffix`, in which case this value is used as the suffix.",
                }),
              statement_descriptor_suffix: z
                .string()
                .max(22)
                .exactOptional()
                .openapi({
                  description:
                    "Provides information about a card charge. Concatenated to the account's [statement descriptor prefix](https://docs.stripe.com/get-started/account/statement-descriptors#static) to form the complete statement descriptor that appears on the customer's statement. If the account has no prefix value, the suffix is concatenated to the account's statement descriptor.",
                }),
              transfer_data: z
                .object({
                  amount: z
                    .preprocess(
                      (val) =>
                        typeof val === 'string' &&
                        /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                        (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                          ? Number(val)
                          : val,
                      z.int(),
                    )
                    .exactOptional(),
                })
                .exactOptional()
                .openapi({
                  description:
                    'An optional dictionary including the account to automatically transfer to as part of a destination charge. [See the Connect documentation](https://docs.stripe.com/connect/destination-charges) for details.',
                  title: 'transfer_data_specs',
                  required: [],
                }),
              transfer_group: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'A string that identifies this transaction as part of a group. `transfer_group` may only be provided if it has not been set. See the [Connect documentation](https://docs.stripe.com/connect/separate-charges-and-transfers#transfer-options) for details.',
                }),
            })
            .openapi({ required: [] }),
          encoding: { expand: {}, transfer_data: {} },
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Successful response.',
      content: { 'application/json': { schema: ChargeSchema } },
    },
    default: {
      description: 'Error response.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
})

