export const getV1FinancialConnectionsAccountsRoute = createRoute({
  method: 'get',
  path: '/v1/financial_connections/accounts',
  summary: 'List Accounts',
  description: '<p>Returns a list of Financial Connections <code>Account</code> objects.</p>',
  operationId: 'GetFinancialConnectionsAccounts',
  request: {
    query: z
      .looseObject({})
      .transform((val) => {
        const rest: [string, unknown][] = []
        const groups = new Map<string, Record<string, unknown>>()
        const group = (name: string) => {
          const found = groups.get(name)
          if (found !== undefined) return found
          const made: Record<string, unknown> = Object.create(null)
          groups.set(name, made)
          return made
        }
        const isGroup = (item: unknown): item is Record<string, unknown> =>
          typeof item === 'object' && item !== null && !Array.isArray(item)
        const lists = new WeakSet<object>()
        const isIndex = (part: string | undefined) => part !== undefined && /^\d*$/.test(part)
        const child = (target: Record<string, unknown>, key: string, asList: boolean) => {
          const held = target[key]
          if (isGroup(held)) return held
          const made: Record<string, unknown> = Object.create(null)
          if (asList) lists.add(made)
          target[key] = made
          return made
        }
        const set = (
          root: Record<string, unknown>,
          path: readonly string[],
          item: unknown,
        ): void => {
          const work: [Record<string, unknown>, number, unknown, boolean][] = [
            [root, 0, item, false],
          ]
          for (let job = work.pop(); job !== undefined; job = work.pop()) {
            const [target, at, value, split] = job
            const head = path[at]
            if (head === undefined) continue
            const next = path[at + 1]
            if (head === '') {
              if (!split && Array.isArray(value)) {
                for (let i = value.length - 1; i >= 0; i -= 1)
                  work.push([target, at, value[i], true])
                continue
              }
              const size = Object.keys(target).length
              if (next === undefined) {
                target[String(size)] = value
                continue
              }
              const free =
                next === ''
                  ? -1
                  : Object.values(target).findIndex((held) => isGroup(held) && !(next in held))
              work.push([
                child(target, String(free < 0 ? size : free), isIndex(next)),
                at + 1,
                value,
                false,
              ])
              continue
            }
            if (next === undefined) {
              target[head] = value
              continue
            }
            work.push([child(target, head, isIndex(next)), at + 1, value, false])
          }
        }
        const settle = (root: unknown): unknown => {
          if (!isGroup(root)) return root
          const found: [Record<string, unknown>, string, Record<string, unknown>][] = []
          const queue: Record<string, unknown>[] = [root]
          for (const node of queue) {
            for (const [key, inner] of Object.entries(node)) {
              if (isGroup(inner)) {
                found.push([node, key, inner])
                queue.push(inner)
              }
            }
          }
          const finish = (group: Record<string, unknown>): unknown =>
            lists.has(group)
              ? Object.entries(group)
                  .sort((a, b) => Number(a[0]) - Number(b[0]))
                  .map(([, inner]) => inner)
              : Object.assign(Object.create(null), group)
          for (const [parent, key, group] of found.reverse()) {
            parent[key] = finish(group)
          }
          return finish(root)
        }
        const deep: string[] = ['account_holder']
        for (const [key, item] of Object.entries(val)) {
          const match = /^([^\[\]]+)((?:\[[^\[\]]*\])+)$/.exec(key)
          const name = match?.[1]
          const path = match?.[2]
          if (name !== undefined && path !== undefined && deep.includes(name)) {
            const parts = path.slice(1, -1).split('][')
            set(group(name), parts, item)
            continue
          }
          rest.push([key, item])
        }
        return Object.fromEntries([
          ...rest,
          ...[...groups].map(([name, held]) => [name, settle(held)] as const),
        ])
      })
      .pipe(
        z.object({
          account_holder: z
            .object({
              account: z.string().max(5000).exactOptional(),
              customer: z.string().max(5000).exactOptional(),
              customer_account: z.string().max(5000).exactOptional(),
            })
            .exactOptional()
            .openapi({
              param: {
                description:
                  'If present, only return accounts that belong to the specified account holder. `account_holder[customer]` and `account_holder[account]` are mutually exclusive.',
                explode: true,
                in: 'query',
                name: 'account_holder',
                required: false,
                schema: {
                  properties: {
                    account: { maxLength: 5000, type: 'string' },
                    customer: { maxLength: 5000, type: 'string' },
                    customer_account: { maxLength: 5000, type: 'string' },
                  },
                  title: 'accountholder_params',
                  type: 'object',
                },
                style: 'deepObject',
              },
              title: 'accountholder_params',
              required: [],
            }),
          ending_before: z
            .string()
            .max(5000)
            .exactOptional()
            .openapi({
              param: {
                description:
                  'A cursor for use in pagination. `ending_before` is an object ID that defines your place in the list. For instance, if you make a list request and receive 100 objects, starting with `obj_bar`, your subsequent call can include `ending_before=obj_bar` in order to fetch the previous page of the list.',
                in: 'query',
                name: 'ending_before',
                required: false,
                schema: { maxLength: 5000, type: 'string' },
                style: 'form',
              },
            }),
          expand: z
            .preprocess(
              (val) => (val === undefined || Array.isArray(val) ? val : [val]),
              z.array(z.string().max(5000)),
            )
            .exactOptional()
            .openapi({
              param: {
                description: 'Specifies which fields in the response should be expanded.',
                explode: true,
                in: 'query',
                name: 'expand',
                required: false,
                schema: { items: { maxLength: 5000, type: 'string' }, type: 'array' },
                style: 'deepObject',
              },
            }),
          limit: z
            .preprocess(
              (val) =>
                typeof val === 'string' &&
                /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                  ? Number(val)
                  : val,
              z.int(),
            )
            .exactOptional()
            .openapi({
              param: {
                description:
                  'A limit on the number of objects to be returned. Limit can range between 1 and 100, and the default is 10.',
                in: 'query',
                name: 'limit',
                required: false,
                schema: { type: 'integer' },
                style: 'form',
              },
            }),
          session: z
            .string()
            .max(5000)
            .exactOptional()
            .openapi({
              param: {
                description:
                  'If present, only return accounts that were collected as part of the given session.',
                in: 'query',
                name: 'session',
                required: false,
                schema: { maxLength: 5000, type: 'string' },
                style: 'form',
              },
            }),
          starting_after: z
            .string()
            .max(5000)
            .exactOptional()
            .openapi({
              param: {
                description:
                  'A cursor for use in pagination. `starting_after` is an object ID that defines your place in the list. For instance, if you make a list request and receive 100 objects, ending with `obj_foo`, your subsequent call can include `starting_after=obj_foo` in order to fetch the next page of the list.',
                in: 'query',
                name: 'starting_after',
                required: false,
                schema: { maxLength: 5000, type: 'string' },
                style: 'form',
              },
            }),
        }),
      ),
    body: { content: { 'application/x-www-form-urlencoded': { schema: z.strictObject({}) } } },
  },
  responses: {
    200: {
      description: 'Successful response.',
      content: {
        'application/json': {
          schema: z
            .object({
              data: z
                .array(FinancialConnectionsAccountSchema)
                .openapi({ description: 'Details about each object.' }),
              has_more: z
                .boolean()
                .openapi({
                  description:
                    'True if this list has another page of items after this one that can be fetched.',
                }),
              object: z
                .literal('list')
                .openapi({
                  description:
                    "String representing the object's type. Objects of the same type share the same value. Always has the value `list`.",
                }),
              url: z
                .string()
                .regex(/^\/v1\/financial_connections\/accounts/)
                .max(5000)
                .openapi({ description: 'The URL where this list can be accessed.' }),
            })
            .openapi({
              description: '',
              required: ['data', 'has_more', 'object', 'url'],
              title: 'BankConnectionsResourceLinkedAccountList',
              'x-expandableFields': ['data'],
            }),
        },
      },
    },
    default: {
      description: 'Error response.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
})

