                                  'hst',
                                  'igst',
                                  'jct',
                                  'lease_tax',
                                  'mass_transit_parking_tax',
                                  'parking_tax',
                                  'pst',
                                  'qst',
                                  'retail_delivery_fee',
                                  'rst',
                                  'sales_tax',
