export const getV1PaymentIntentsSearchRoute = createRoute({
  method: 'get',
  path: '/v1/payment_intents/search',
  summary: 'Search PaymentIntents',
  description:
    '<p>Search for PaymentIntents you’ve previously created using Stripe’s <a href="/docs/search#search-query-language">Search Query Language</a>.\nDon’t use search in read-after-write flows where strict consistency is necessary. Under normal operating\nconditions, data is searchable in less than a minute. Occasionally, propagation of new or updated data can be up\nto an hour behind during outages. Search functionality is not available to merchants in India.</p>',
  operationId: 'GetPaymentIntentsSearch',
  request: {
    query: z.object({
      expand: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.string().max(5000)),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'Specifies which fields in the response should be expanded.',
            explode: true,
            in: 'query',
            name: 'expand',
            required: false,
            schema: { items: { maxLength: 5000, type: 'string' }, type: 'array' },
            style: 'deepObject',
          },
        }),
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'A limit on the number of objects to be returned. Limit can range between 1 and 100, and the default is 10.',
            in: 'query',
            name: 'limit',
            required: false,
            schema: { type: 'integer' },
            style: 'form',
          },
        }),
      page: z
        .string()
        .max(5000)
        .exactOptional()
        .openapi({
          param: {
            description:
              "A cursor for pagination across multiple pages of results. Don't include this parameter on the first call. Use the next_page value returned in a previous response to request subsequent results.",
            in: 'query',
            name: 'page',
            required: false,
            schema: { maxLength: 5000, type: 'string' },
            style: 'form',
          },
        }),
      query: z
        .string()
        .max(5000)
        .openapi({
          param: {
            description:
              'The search query string. See [search query language](https://docs.stripe.com/search#search-query-language) and the list of supported [query fields for payment intents](https://docs.stripe.com/search#query-fields-for-paymentintents).',
            in: 'query',
            name: 'query',
            required: true,
            schema: { maxLength: 5000, type: 'string' },
            style: 'form',
          },
        }),
    }),
    body: { content: { 'application/x-www-form-urlencoded': { schema: z.strictObject({}) } } },
  },
  responses: {
    200: {
      description: 'Successful response.',
      content: {
        'application/json': {
          schema: z
            .object({
              data: z.array(PaymentIntentSchema),
              has_more: z.boolean(),
              next_page: z.string().max(5000).nullable().exactOptional(),
              object: z
                .literal('search_result')
                .openapi({
                  description:
                    "String representing the object's type. Objects of the same type share the same value.",
                }),
              total_count: z
                .int()
                .exactOptional()
                .openapi({
                  description:
                    'The total number of objects that match the query, only accurate up to 10,000.',
                }),
              url: z.string().max(5000),
            })
            .openapi({
              description: '',
              required: ['data', 'has_more', 'object', 'url'],
              title: 'SearchResult',
              'x-expandableFields': ['data'],
            }),
        },
      },
    },
    default: {
      description: 'Error response.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
})

