export const postV1PlansRoute = createRoute({
  method: 'post',
  path: '/v1/plans',
  summary: 'Create a plan',
  description:
    '<p>You can now model subscriptions more flexibly using the <a href="#prices">Prices API</a>. It replaces the Plans API and is backwards compatible to simplify your migration.</p>',
  operationId: 'PostPlans',
  request: {
    body: {
      content: {
        'application/x-www-form-urlencoded': {
          schema: z
            .strictObject({
              active: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .exactOptional()
                .openapi({
                  description:
                    'Whether the plan is currently available for new subscriptions. Defaults to `true`.',
                }),
              amount: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .exactOptional()
                .openapi({
                  description:
                    'A positive integer in cents (or local equivalent) (or 0 for a free plan) representing how much to charge on a recurring basis.',
                }),
              amount_decimal: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Same as `amount`, but accepts a decimal value with at most 12 decimal places. Only one of `amount` and `amount_decimal` can be set.',
                }),
              billing_scheme: z
                .enum(['per_unit', 'tiered'])
                .exactOptional()
                .openapi({
                  description:
                    'Describes how to compute the price per period. Either `per_unit` or `tiered`. `per_unit` indicates that the fixed amount (specified in `amount`) will be charged per unit in `quantity` (for plans with `usage_type=licensed`), or per unit of total usage (for plans with `usage_type=metered`). `tiered` indicates that the unit pricing will be computed using a tiering strategy as defined using the `tiers` and `tiers_mode` attributes.',
                }),
              currency: z
                .string()
                .openapi({
                  description:
                    'Three-letter [ISO currency code](https://www.iso.org/iso-4217-currency-codes.html), in lowercase. Must be a [supported currency](https://stripe.com/docs/currencies).',
                }),
              expand: z
                .preprocess(
                  (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                  z.array(z.string().max(5000)),
                )
                .exactOptional()
                .openapi({
                  description: 'Specifies which fields in the response should be expanded.',
                }),
              id: z
                .string()
                .max(5000)
                .exactOptional()
                .openapi({
                  description:
                    'An identifier randomly generated by Stripe. Used to identify this plan when subscribing a customer. You can optionally override this ID, but the ID must be unique across all plans in your Stripe account. You can use the same plan ID in live mode and in your sandboxes.',
                }),
              interval: z
                .enum(['day', 'month', 'week', 'year'])
                .openapi({
                  description:
                    'Specifies billing frequency. Either `day`, `week`, `month` or `year`.',
                }),
              interval_count: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .exactOptional()
                .openapi({
                  description:
                    'The number of intervals between subscription billings. For example, `interval=month` and `interval_count=3` bills every 3 months. Maximum of three years interval allowed (3 years, 36 months, or 156 weeks).',
                }),
              metadata: z
                .union([z.record(z.string(), z.string()), z.literal('')])
                .exactOptional()
                .openapi({
                  description:
                    'Set of [key-value pairs](https://docs.stripe.com/api/metadata) that you can attach to an object. This can be useful for storing additional information about the object in a structured format. Individual keys can be unset by posting an empty value to them. All keys can be unset by posting an empty value to `metadata`.',
                }),
              meter: z
                .string()
                .max(5000)
                .exactOptional()
                .openapi({ description: 'The meter tracking the usage of a metered price' }),
              nickname: z
                .string()
                .max(5000)
                .exactOptional()
                .openapi({
                  description: 'A brief description of the plan, hidden from customers.',
                }),
              product: z
                .union([
                  z
                    .object({
                      active: z
                        .preprocess(
                          ((read) => (val: unknown) => {
                            const result = read.safeParse(val)
                            return result.success ? result.data : val
                          })(z.stringbool()),
                          z.boolean(),
                        )
                        .exactOptional(),
                      id: z.string().max(5000).exactOptional().openapi({ deprecated: true }),
                      metadata: z.record(z.string(), z.string()).exactOptional(),
                      name: z.string().max(5000),
                      statement_descriptor: z.string().max(22).exactOptional(),
                      tax_code: z.string().max(5000).exactOptional(),
                      tax_details: z
                        .object({
                          performance_location: z.string().max(5000).exactOptional(),
                          tax_code: z.union([z.string(), z.literal('')]).exactOptional(),
                        })
                        .exactOptional()
                        .openapi({ title: 'tax_details', required: [] }),
                      unit_label: z.string().max(12).exactOptional(),
                    })
                    .openapi({
                      description:
                        'The product whose pricing the created plan will represent. This can either be the ID of an existing product, or a dictionary containing fields used to create a [service product](https://docs.stripe.com/api#product_object-type).',
                      required: ['name'],
                      title: 'inline_product_params',
                    }),
                  z
                    .string()
                    .max(5000)
                    .openapi({
                      description:
                        'The ID of the product whose pricing the created plan will represent.',
                    }),
                ])
                .exactOptional(),
              tiers: z
                .preprocess(
                  (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                  z.array(
                    z
                      .object({
                        flat_amount: z
                          .preprocess(
                            (val) =>
                              typeof val === 'string' &&
                              /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                              (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                                ? Number(val)
                                : val,
                            z.int(),
                          )
                          .exactOptional(),
                        flat_amount_decimal: z.string().exactOptional(),
                        unit_amount: z
                          .preprocess(
                            (val) =>
                              typeof val === 'string' &&
                              /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                              (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                                ? Number(val)
                                : val,
                            z.int(),
                          )
                          .exactOptional(),
                        unit_amount_decimal: z.string().exactOptional(),
                        up_to: ((schema) =>
                          z.union([
                            z.preprocess(
                              (val) =>
                                typeof val === 'string' &&
                                /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                                (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                                  ? Number(val)
                                  : val,
                              schema,
                            ),
                            schema,
                          ]))(z.union([z.literal('inf'), z.int()])),
                      })
                      .openapi({ required: ['up_to'], title: 'tier' }),
                  ),
                )
                .exactOptional()
                .openapi({
                  description:
                    'Each element represents a pricing tier. This parameter requires `billing_scheme` to be set to `tiered`. See also the documentation for `billing_scheme`.',
                }),
              tiers_mode: z
                .enum(['graduated', 'volume'])
                .exactOptional()
                .openapi({
                  description:
                    'Defines if the tiering price should be `graduated` or `volume` based. In `volume`-based tiering, the maximum quantity within a period determines the per unit price, in `graduated` tiering pricing can successively change as the quantity grows.',
                }),
              transform_usage: z
                .object({
                  divide_by: z.preprocess(
                    (val) =>
                      typeof val === 'string' &&
                      /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                      (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                        ? Number(val)
                        : val,
                    z.int(),
                  ),
                  round: z.enum(['down', 'up']),
                })
                .exactOptional()
                .openapi({
                  description:
                    'Apply a transformation to the reported usage or set quantity before computing the billed price. Cannot be combined with `tiers`.',
                  required: ['divide_by', 'round'],
                  title: 'transform_usage_param',
                }),
              trial_period_days: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .exactOptional()
                .openapi({
                  description:
                    'Default number of trial days when subscribing a customer to this plan using [`trial_from_plan=true`](https://docs.stripe.com/api#create_subscription-trial_from_plan).',
                }),
              usage_type: z
                .enum(['licensed', 'metered'])
                .exactOptional()
                .openapi({
                  description:
                    'Configures how the quantity per period should be determined. Can be either `metered` or `licensed`. `licensed` automatically bills the `quantity` set when adding it to a subscription. `metered` aggregates the total usage based on usage records. Defaults to `licensed`.',
                }),
            })
            .openapi({ required: ['currency', 'interval'] }),
          encoding: { expand: {}, metadata: {}, product: {}, tiers: {}, transform_usage: {} },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Successful response.',
      content: { 'application/json': { schema: PlanSchema } },
    },
    default: {
      description: 'Error response.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
})

