          recurring: z
            .object({
              interval: z.enum(['day', 'month', 'week', 'year']).exactOptional(),
              meter: z.string().max(5000).exactOptional(),
              usage_type: z.enum(['licensed', 'metered']).exactOptional(),
            })
            .exactOptional()
