export const postV1RefundsRoute = createRoute({
  method: 'post',
  path: '/v1/refunds',
  summary: 'Create a refund',
  description:
    '<p>When you create a new refund, you must specify a Charge or a PaymentIntent object on which to create it.</p>\n\n<p>Creating a new refund will refund a charge that has previously been created but not yet refunded.\nFunds will be refunded to the credit or debit card that was originally charged.</p>\n\n<p>You can optionally refund only part of a charge.\nYou can do so multiple times, until the entire charge has been refunded.</p>\n\n<p>Once entirely refunded, a charge can’t be refunded again.\nThis method will raise an error when called on an already-refunded charge,\nor when trying to refund more money than is left on a charge.</p>',
  operationId: 'PostRefunds',
  request: {
    body: {
      content: {
        'application/x-www-form-urlencoded': {
          schema: z
            .strictObject({
              amount: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .exactOptional(),
              charge: z
                .string()
                .max(5000)
                .exactOptional()
                .openapi({ description: 'The identifier of the charge to refund.' }),
              currency: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Three-letter [ISO currency code](https://www.iso.org/iso-4217-currency-codes.html), in lowercase. Must be a [supported currency](https://stripe.com/docs/currencies).',
                }),
              customer: z
                .string()
                .max(5000)
                .exactOptional()
                .openapi({ description: 'Customer whose customer balance to refund from.' }),
              expand: z
                .preprocess(
                  (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                  z.array(z.string().max(5000)),
                )
                .exactOptional()
                .openapi({
                  description: 'Specifies which fields in the response should be expanded.',
                }),
              instructions_email: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'For payment methods without native refund support (e.g., Konbini, PromptPay), use this email from the customer to receive refund instructions.',
                }),
              metadata: z
                .union([z.record(z.string(), z.string()), z.literal('')])
                .exactOptional()
                .openapi({
                  description:
                    'Set of [key-value pairs](https://docs.stripe.com/api/metadata) that you can attach to an object. This can be useful for storing additional information about the object in a structured format. Individual keys can be unset by posting an empty value to them. All keys can be unset by posting an empty value to `metadata`.',
                }),
              origin: z
                .literal('customer_balance')
                .exactOptional()
                .openapi({ description: 'Origin of the refund' }),
              payment_intent: z
                .string()
                .max(5000)
                .exactOptional()
                .openapi({ description: 'The identifier of the PaymentIntent to refund.' }),
              reason: z
                .enum(['duplicate', 'fraudulent', 'requested_by_customer'])
                .exactOptional()
                .openapi({
                  description:
                    'String indicating the reason for the refund. If set, possible values are `duplicate`, `fraudulent`, and `requested_by_customer`. If you believe the charge to be fraudulent, specifying `fraudulent` as the reason will add the associated card and email to your [block lists](https://docs.stripe.com/radar/lists), and will also help us improve our fraud detection algorithms.',
                }),
              refund_application_fee: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .exactOptional()
                .openapi({
                  description:
                    'Boolean indicating whether the application fee should be refunded when refunding this charge. If a full charge refund is given, the full application fee will be refunded. Otherwise, the application fee will be refunded in an amount proportional to the amount of the charge refunded. An application fee can be refunded only by the application that created the charge.',
                }),
              reverse_transfer: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .exactOptional()
                .openapi({
                  description:
                    'Boolean indicating whether the transfer should be reversed when refunding this charge. The transfer will be reversed proportionally to the amount being refunded (either the entire or partial amount).<br><br>A transfer can be reversed only by the application that created the charge.',
                }),
            })
            .openapi({ required: [] }),
          encoding: { expand: {}, metadata: {} },
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Successful response.',
      content: { 'application/json': { schema: RefundSchema } },
    },
    default: {
      description: 'Error response.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
})

