export const getV1SetupIntentsIntentRoute = createRoute({
  method: 'get',
  path: '/v1/setup_intents/{intent}',
  summary: 'Retrieve a SetupIntent',
  description:
    '<p>Retrieves the details of a SetupIntent that has previously been created. </p>\n\n<p>Client-side retrieval using a publishable key is allowed when the <code>client_secret</code> is provided in the query string. </p>\n\n<p>When retrieved with a publishable key, only a subset of properties will be returned. Please refer to the <a href="#setup_intent_object">SetupIntent</a> object reference for more details.</p>',
  operationId: 'GetSetupIntentsIntent',
  request: {
    query: z.object({
      client_secret: z
        .string()
        .max(5000)
        .exactOptional()
        .openapi({
          param: {
            description:
              'The client secret of the SetupIntent. We require this string if you use a publishable key to retrieve the SetupIntent.',
            in: 'query',
            name: 'client_secret',
            required: false,
            schema: { maxLength: 5000, type: 'string' },
            style: 'form',
          },
        }),
      expand: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.string().max(5000)),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'Specifies which fields in the response should be expanded.',
            explode: true,
            in: 'query',
            name: 'expand',
            required: false,
            schema: { items: { maxLength: 5000, type: 'string' }, type: 'array' },
            style: 'deepObject',
          },
        }),
    }),
    params: z.object({
      intent: z
        .string()
        .max(5000)
        .openapi({
          param: {
            in: 'path',
            name: 'intent',
            required: true,
            schema: { maxLength: 5000, type: 'string' },
            style: 'simple',
          },
        }),
    }),
    body: { content: { 'application/x-www-form-urlencoded': { schema: z.strictObject({}) } } },
  },
  responses: {
    200: {
      description: 'Successful response.',
      content: { 'application/json': { schema: SetupIntentSchema } },
    },
    default: {
      description: 'Error response.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
})

