export const postV1SetupIntentsIntentCancelRoute = createRoute({
  method: 'post',
  path: '/v1/setup_intents/{intent}/cancel',
  summary: 'Cancel a SetupIntent',
  description:
    '<p>You can cancel a SetupIntent object when it’s in one of these statuses: <code>requires_payment_method</code>, <code>requires_confirmation</code>, or <code>requires_action</code>. </p>\n\n<p>After you cancel it, setup is abandoned and any operations on the SetupIntent fail with an error. You can’t cancel the SetupIntent for a Checkout Session. <a href="/docs/api/checkout/sessions/expire">Expire the Checkout Session</a> instead.</p>',
  operationId: 'PostSetupIntentsIntentCancel',
  request: {
    params: z.object({
      intent: z
        .string()
        .max(5000)
        .openapi({
          param: {
            in: 'path',
            name: 'intent',
            required: true,
            schema: { maxLength: 5000, type: 'string' },
            style: 'simple',
          },
        }),
    }),
    body: {
      content: {
        'application/x-www-form-urlencoded': {
          schema: z
            .strictObject({
              cancellation_reason: z
                .enum(['abandoned', 'duplicate', 'requested_by_customer'])
                .exactOptional()
                .openapi({
                  description:
                    'Reason for canceling this SetupIntent. Possible values are: `abandoned`, `requested_by_customer`, or `duplicate`',
                }),
              expand: z
                .preprocess(
                  (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                  z.array(z.string().max(5000)),
                )
                .exactOptional()
                .openapi({
                  description: 'Specifies which fields in the response should be expanded.',
                }),
            })
            .openapi({ required: [] }),
          encoding: { expand: {} },
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Successful response.',
      content: { 'application/json': { schema: SetupIntentSchema } },
    },
    default: {
      description: 'Error response.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
})

