export const postV1SourcesRoute = createRoute({
  method: 'post',
  path: '/v1/sources',
  summary: 'Create a source',
  description: '<p>Creates a new source object.</p>',
  operationId: 'PostSources',
  request: {
    body: {
      content: {
        'application/x-www-form-urlencoded': {
          schema: z
            .strictObject({
              amount: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .exactOptional()
                .openapi({
                  description:
                    'Amount associated with the source. This is the amount for which the source will be chargeable once ready. Required for `single_use` sources. Not supported for `receiver` type sources, where charge amount may not be specified until funds land.',
                }),
              currency: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Three-letter [ISO code for the currency](https://stripe.com/docs/currencies) associated with the source. This is the currency for which the source will be chargeable once ready.',
                }),
              customer: z
                .string()
                .max(500)
                .exactOptional()
                .openapi({
                  description:
                    'The `Customer` to whom the original source is attached to. Must be set when the original source is not a `Source` (e.g., `Card`).',
                }),
              expand: z
                .preprocess(
                  (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                  z.array(z.string().max(5000)),
                )
                .exactOptional()
                .openapi({
                  description: 'Specifies which fields in the response should be expanded.',
                }),
              flow: z
                .enum(['code_verification', 'none', 'receiver', 'redirect'])
                .exactOptional()
                .openapi({
                  description:
                    'The authentication `flow` of the source to create. `flow` is one of `redirect`, `receiver`, `code_verification`, `none`. It is generally inferred unless a type supports multiple flows.',
                }),
              mandate: z
                .object({
                  acceptance: z
                    .object({
                      date: z
                        .preprocess(
                          (val) =>
                            typeof val === 'string' &&
                            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                              ? Number(val)
                              : val,
                          z.int(),
                        )
                        .exactOptional(),
                      ip: z.string().exactOptional(),
                      offline: z
                        .object({ contact_email: z.string() })
                        .exactOptional()
                        .openapi({
                          required: ['contact_email'],
                          title: 'mandate_offline_acceptance_params',
                        }),
                      online: z
                        .object({
                          date: z
                            .preprocess(
                              (val) =>
                                typeof val === 'string' &&
                                /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                                (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                                  ? Number(val)
                                  : val,
                              z.int(),
                            )
                            .exactOptional(),
                          ip: z.string().exactOptional(),
                          user_agent: z.string().max(5000).exactOptional(),
                        })
                        .exactOptional()
                        .openapi({ title: 'mandate_online_acceptance_params', required: [] }),
                      status: z.enum(['accepted', 'pending', 'refused', 'revoked']),
                      type: z.enum(['offline', 'online']).exactOptional(),
                      user_agent: z.string().max(5000).exactOptional(),
                    })
                    .exactOptional()
                    .openapi({ required: ['status'], title: 'mandate_acceptance_params' }),
                  amount: ((schema) =>
                    z.union([
                      z.preprocess(
                        (val) =>
                          typeof val === 'string' &&
                          /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                          (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                            ? Number(val)
                            : val,
                        schema,
                      ),
                      schema,
                    ]))(z.union([z.int(), z.literal('')])).exactOptional(),
                  currency: z.string().exactOptional(),
                  interval: z.enum(['one_time', 'scheduled', 'variable']).exactOptional(),
                  notification_method: z
                    .enum(['deprecated_none', 'email', 'manual', 'none', 'stripe_email'])
                    .exactOptional(),
                })
                .exactOptional()
                .openapi({
                  description:
                    'Information about a mandate possibility attached to a source object (generally for bank debits) as well as its acceptance status.',
                  title: 'mandate_params',
                  required: [],
                }),
              metadata: z.record(z.string(), z.string()).exactOptional(),
              original_source: z
                .string()
                .max(5000)
                .exactOptional()
                .openapi({ description: 'The source to share.' }),
              owner: z
                .object({
                  address: z
                    .object({
                      city: z.string().max(5000).exactOptional(),
                      country: z.string().max(5000).exactOptional(),
                      line1: z.string().max(5000).exactOptional(),
                      line2: z.string().max(5000).exactOptional(),
                      postal_code: z.string().max(5000).exactOptional(),
                      state: z.string().max(5000).exactOptional(),
                    })
                    .exactOptional()
                    .openapi({ title: 'source_address', required: [] }),
                  email: z.string().exactOptional(),
                  name: z.string().max(5000).exactOptional(),
                  phone: z.string().max(5000).exactOptional(),
                })
                .exactOptional()
                .openapi({
                  description:
                    'Information about the owner of the payment instrument that may be used or required by particular source types.',
                  title: 'owner',
                  required: [],
                }),
              receiver: z
                .object({
                  refund_attributes_method: z.enum(['email', 'manual', 'none']).exactOptional(),
                })
                .exactOptional()
                .openapi({
                  description:
                    'Optional parameters for the receiver flow. Can be set only if the source is a receiver (`flow` is `receiver`).',
                  title: 'receiver_params',
                  required: [],
                }),
              redirect: z
                .object({ return_url: z.string() })
                .exactOptional()
                .openapi({
                  description:
                    'Parameters required for the redirect flow. Required if the source is authenticated by a redirect (`flow` is `redirect`).',
                  required: ['return_url'],
                  title: 'redirect_params',
                }),
              source_order: z
                .object({
                  items: z
                    .preprocess(
                      (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                      z.array(
                        z
                          .object({
                            amount: z
                              .preprocess(
                                (val) =>
                                  typeof val === 'string' &&
                                  /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                                  (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                                    ? Number(val)
                                    : val,
                                z.int(),
                              )
                              .exactOptional(),
                            currency: z.string().exactOptional(),
                            description: z.string().max(1000).exactOptional(),
                            parent: z.string().max(5000).exactOptional(),
                            quantity: z
                              .preprocess(
                                (val) =>
                                  typeof val === 'string' &&
                                  /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                                  (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                                    ? Number(val)
                                    : val,
                                z.int(),
                              )
                              .exactOptional(),
                            type: z.enum(['discount', 'shipping', 'sku', 'tax']).exactOptional(),
                          })
                          .openapi({ title: 'order_item_specs', required: [] }),
                      ),
                    )
                    .exactOptional(),
                  shipping: z
                    .object({
                      address: z
                        .object({
                          city: z.string().max(5000).exactOptional(),
                          country: z.string().max(5000).exactOptional(),
                          line1: z.string().max(5000),
                          line2: z.string().max(5000).exactOptional(),
                          postal_code: z.string().max(5000).exactOptional(),
                          state: z.string().max(5000).exactOptional(),
                        })
                        .openapi({ required: ['line1'], title: 'address' }),
                      carrier: z.string().max(5000).exactOptional(),
                      name: z.string().max(5000).exactOptional(),
                      phone: z.string().max(5000).exactOptional(),
                      tracking_number: z.string().max(5000).exactOptional(),
                    })
                    .exactOptional()
                    .openapi({ required: ['address'], title: 'order_shipping' }),
                })
                .exactOptional()
                .openapi({
                  description:
                    'Information about the items and shipping associated with the source. Required for transactional credit (for example Klarna) sources before you can charge it.',
                  title: 'shallow_order_specs',
                  required: [],
                }),
              statement_descriptor: z
                .string()
                .max(5000)
                .exactOptional()
                .openapi({
                  description:
                    "An arbitrary string to be displayed on your customer's statement. As an example, if your website is `RunClub` and the item you're charging for is a race ticket, you may want to specify a `statement_descriptor` of `RunClub 5K race ticket.` While many payment types will display this information, some may not display it at all.",
                }),
              token: z
                .string()
                .max(5000)
                .exactOptional()
                .openapi({
                  description:
                    'An optional token used to create the source. When passed, token properties will override source parameters.',
                }),
              type: z
                .string()
                .max(5000)
                .exactOptional()
                .openapi({
                  description:
                    'The `type` of the source to create. Required unless `customer` and `original_source` are specified (see the [Cloning card Sources](https://docs.stripe.com/sources/connect#cloning-card-sources) guide)',
                }),
              usage: z.enum(['reusable', 'single_use']).exactOptional(),
            })
            .openapi({ required: [] }),
          encoding: {
            expand: {},
            mandate: {},
            metadata: {},
            owner: {},
            receiver: {},
            redirect: {},
            source_order: {},
          },
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Successful response.',
      content: { 'application/json': { schema: SourceSchema } },
    },
    default: {
      description: 'Error response.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
})

