export const postV1SubscriptionsSubscriptionResumeRoute = createRoute({
  method: 'post',
  path: '/v1/subscriptions/{subscription}/resume',
  summary: 'Resume a subscription',
  description:
    '<p>Initiates resumption of a paused subscription, optionally resetting the billing cycle anchor and creating prorations. Resume is only available for subscriptions that use <code>charge_automatically</code> collection. If Stripe doesn’t generate a resumption invoice, the subscription becomes <code>active</code> immediately. When a resumption invoice is generated, Stripe finalizes it immediately. If the invoice is paid or marked uncollectible, the subscription becomes <code>active</code>. If the invoice is manually voided, the subscription stays <code>paused</code>. If there is no payment attempt within 23 hours, Stripe voids the invoice and the subscription stays <code>paused</code>. Learn more about <a href="/docs/billing/subscriptions/pause#resume-subscriptions">resuming subscriptions</a>.</p>',
  operationId: 'PostSubscriptionsSubscriptionResume',
  request: {
    params: z.object({
      subscription: z
        .string()
        .max(5000)
        .openapi({
          param: {
            in: 'path',
            name: 'subscription',
            required: true,
            schema: { maxLength: 5000, type: 'string' },
            style: 'simple',
          },
        }),
    }),
    body: {
      content: {
        'application/x-www-form-urlencoded': {
          schema: z
            .strictObject({
              billing_cycle_anchor: z
                .object({
                  type: z.enum(['now', 'unchanged']).openapi({ 'x-stripeBypassValidation': true }),
                })
                .exactOptional()
                .openapi({
                  description:
                    'The billing cycle anchor that applies when the subscription is resumed. Either `now` or `unchanged`. The default is `now`. For more information, see the billing cycle [documentation](https://docs.stripe.com/billing/subscriptions/billing-cycle).',
                  required: ['type'],
                  title: 'billing_cycle_anchor_param',
                }),
              expand: z
                .preprocess(
                  (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                  z.array(z.string().max(5000)),
                )
                .exactOptional()
                .openapi({
                  description: 'Specifies which fields in the response should be expanded.',
                }),
              payment_behavior: z
                .enum(['resume_on_payment_attempt', 'resume_on_payment_success'])
                .exactOptional()
                .openapi({
                  description:
                    "Controls whether Stripe attempts payment on the resumption invoice in the resume request, and how payment on that invoice affects the subscription's status. The default is `resume_on_payment_attempt`.",
                }),
              proration_behavior: z
                .enum(['always_invoice', 'create_prorations', 'none'])
                .exactOptional()
                .openapi({
                  description:
                    'Determines how to handle [prorations](https://docs.stripe.com/billing/subscriptions/prorations) resulting from the `billing_cycle_anchor` being `unchanged`. When the `billing_cycle_anchor` is set to `now` (default value), no prorations are generated. If no value is passed, the default is `create_prorations`.',
                }),
              proration_date: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .exactOptional()
                .openapi({
                  description:
                    'If set, prorations will be calculated as though the subscription was resumed at the given time. This can be used to apply exactly the same prorations that were previewed with the [create preview](https://stripe.com/docs/api/invoices/create_preview) endpoint.',
                }),
            })
            .openapi({ required: [] }),
          encoding: { billing_cycle_anchor: {}, expand: {} },
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Successful response.',
      content: { 'application/json': { schema: SubscriptionSchema } },
    },
    default: {
      description: 'Error response.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
})

