export const postV1TaxRegistrationsIdRoute = createRoute({
  method: 'post',
  path: '/v1/tax/registrations/{id}',
  summary: 'Update a registration',
  description:
    '<p>Updates an existing Tax <code>Registration</code> object.</p>\n\n<p>A registration cannot be deleted after it has been created. If you wish to end a registration you may do so by setting <code>expires_at</code>.</p>',
  operationId: 'PostTaxRegistrationsId',
  request: {
    params: z.object({
      id: z
        .string()
        .max(5000)
        .openapi({
          param: {
            in: 'path',
            name: 'id',
            required: true,
            schema: { maxLength: 5000, type: 'string' },
            style: 'simple',
          },
        }),
    }),
    body: {
      content: {
        'application/x-www-form-urlencoded': {
          schema: z
            .strictObject({
              active_from: ((schema) =>
                z.union([
                  z.preprocess(
                    (val) =>
                      typeof val === 'string' &&
                      /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                      (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                        ? Number(val)
                        : val,
                    schema,
                  ),
                  schema,
                ]))(z.union([z.literal('now'), z.int()]))
                .exactOptional()
                .openapi({
                  description:
                    'Time at which the registration becomes active. It can be either `now` to indicate the current time, or a timestamp measured in seconds since the Unix epoch.',
                }),
              expand: z
                .preprocess(
                  (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                  z.array(z.string().max(5000)),
                )
                .exactOptional()
                .openapi({
                  description: 'Specifies which fields in the response should be expanded.',
                }),
              expires_at: ((schema) =>
                z.union([
                  z.preprocess(
                    (val) =>
                      typeof val === 'string' &&
                      /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                      (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                        ? Number(val)
                        : val,
                    schema,
                  ),
                  schema,
                ]))(z.union([z.literal('now'), z.int(), z.literal('')]))
                .exactOptional()
                .openapi({
                  description:
                    'If set, the registration stops being active at this time. If not set, the registration will be active indefinitely. It can be either `now` to indicate the current time, or a timestamp measured in seconds since the Unix epoch.',
                }),
            })
            .openapi({ required: [] }),
          encoding: { active_from: {}, expand: {}, expires_at: {} },
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Successful response.',
      content: { 'application/json': { schema: TaxRegistrationSchema } },
    },
    default: {
      description: 'Error response.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
})

