export const getV1TerminalConfigurationsConfigurationRoute = createRoute({
  method: 'get',
  path: '/v1/terminal/configurations/{configuration}',
  summary: 'Retrieve a Configuration',
  description: '<p>Retrieves a <code>Configuration</code> object.</p>',
  operationId: 'GetTerminalConfigurationsConfiguration',
  request: {
    params: z.object({
      configuration: z
        .string()
        .max(5000)
        .openapi({
          param: {
            in: 'path',
            name: 'configuration',
            required: true,
            schema: { maxLength: 5000, type: 'string' },
            style: 'simple',
          },
        }),
    }),
    query: z.object({
      expand: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.string().max(5000)),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'Specifies which fields in the response should be expanded.',
            explode: true,
            in: 'query',
            name: 'expand',
            required: false,
            schema: { items: { maxLength: 5000, type: 'string' }, type: 'array' },
            style: 'deepObject',
          },
        }),
    }),
    body: { content: { 'application/x-www-form-urlencoded': { schema: z.strictObject({}) } } },
  },
  responses: {
    200: {
      description: 'Successful response.',
      content: {
        'application/json': {
          schema: z.union([TerminalConfigurationSchema, DeletedTerminalConfigurationSchema]),
        },
      },
    },
    default: {
      description: 'Error response.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
})

