export const postV1TestHelpersCustomersCustomerFundCashBalanceRoute = createRoute({
  method: 'post',
  path: '/v1/test_helpers/customers/{customer}/fund_cash_balance',
  summary: 'Fund a test mode cash balance',
  description: '<p>Create an incoming testmode bank transfer</p>',
  operationId: 'PostTestHelpersCustomersCustomerFundCashBalance',
  request: {
    params: z.object({
      customer: z
        .string()
        .max(5000)
        .openapi({
          param: {
            in: 'path',
            name: 'customer',
            required: true,
            schema: { maxLength: 5000, type: 'string' },
            style: 'simple',
          },
        }),
    }),
    body: {
      content: {
        'application/x-www-form-urlencoded': {
          schema: z
            .strictObject({
              amount: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .openapi({
                  description:
                    'Amount to be used for this test cash balance transaction. A positive integer representing how much to fund in the [smallest currency unit](https://docs.stripe.com/currencies#zero-decimal) (e.g., 100 cents to fund $1.00 or 100 to fund ¥100, a zero-decimal currency).',
                }),
              currency: z
                .string()
                .openapi({
                  description:
                    'Three-letter [ISO currency code](https://www.iso.org/iso-4217-currency-codes.html), in lowercase. Must be a [supported currency](https://stripe.com/docs/currencies).',
                }),
              expand: z
                .preprocess(
                  (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                  z.array(z.string().max(5000)),
                )
                .exactOptional()
                .openapi({
                  description: 'Specifies which fields in the response should be expanded.',
                }),
              reference: z
                .string()
                .max(5000)
                .exactOptional()
                .openapi({
                  description:
                    "A description of the test funding. This simulates free-text references supplied by customers when making bank transfers to their cash balance. You can use this to test how Stripe's [reconciliation algorithm](https://docs.stripe.com/payments/customer-balance/reconciliation) applies to different user inputs.",
                }),
            })
            .openapi({ required: ['amount', 'currency'] }),
          encoding: { expand: {} },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Successful response.',
      content: { 'application/json': { schema: CustomerCashBalanceTransactionSchema } },
    },
    default: {
      description: 'Error response.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
})

