export const postV1TestHelpersIssuingSettlementsRoute = createRoute({
  method: 'post',
  path: '/v1/test_helpers/issuing/settlements',
  summary: 'Create a test-mode settlement',
  description: '<p>Allows the user to create an Issuing settlement.</p>',
  operationId: 'PostTestHelpersIssuingSettlements',
  request: {
    body: {
      content: {
        'application/x-www-form-urlencoded': {
          schema: z
            .strictObject({
              bin: z
                .string()
                .max(5000)
                .openapi({
                  description: 'The Bank Identification Number reflecting this settlement record.',
                }),
              clearing_date: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .openapi({
                  description:
                    "The date that the transactions are cleared and posted to user's accounts.",
                }),
              currency: z
                .string()
                .openapi({
                  description:
                    'Three-letter [ISO currency code](https://www.iso.org/iso-4217-currency-codes.html), in lowercase. Must be a [supported currency](https://stripe.com/docs/currencies).',
                }),
              expand: z
                .preprocess(
                  (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                  z.array(z.string().max(5000)),
                )
                .exactOptional()
                .openapi({
                  description: 'Specifies which fields in the response should be expanded.',
                }),
              interchange_fees_amount: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .exactOptional()
                .openapi({
                  description:
                    'The total interchange received as reimbursement for the transactions.',
                }),
              net_total_amount: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .openapi({
                  description: 'The total net amount required to settle with the network.',
                }),
              network: z
                .enum(['maestro', 'visa'])
                .exactOptional()
                .openapi({
                  description:
                    'The card network for this settlement. One of ["visa", "maestro", "mastercard"]',
                  'x-stripeBypassValidation': true,
                }),
              network_settlement_identifier: z
                .string()
                .max(5000)
                .exactOptional()
                .openapi({
                  description: 'The Settlement Identification Number assigned by the network.',
                }),
              transaction_amount: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .exactOptional()
                .openapi({
                  description: 'The total transaction amount reflected in this settlement.',
                }),
              transaction_count: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .exactOptional()
                .openapi({
                  description: 'The total number of transactions reflected in this settlement.',
                }),
            })
            .openapi({ required: ['bin', 'clearing_date', 'currency', 'net_total_amount'] }),
          encoding: { expand: {} },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Successful response.',
      content: { 'application/json': { schema: IssuingSettlementSchema } },
    },
    default: {
      description: 'Error response.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
})

